-- ----------------------------
-- Table structure for emp
-- ----------------------------
DROP TABLE IF EXISTS `emp`;
CREATE TABLE `emp`  (
  `employee_id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `employee_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Nomor Induk Pegawai',
  `device_pin` int UNSIGNED NULL DEFAULT NULL COMMENT 'Nomor pin yang ada di fingerspot',
  `full_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `is_active` tinyint UNSIGNED NULL DEFAULT 1 COMMENT 'active atau tidak',
  `gender` tinyint UNSIGNED NULL DEFAULT NULL,
  `hire_date` date NULL DEFAULT NULL,
  `birth_date` date NULL DEFAULT NULL,
  `resign_date` date NULL DEFAULT NULL,
  `retire_date` date NULL DEFAULT NULL,
  `emp_type_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT 'Link to emp_type',
  `emp_level` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Link to emp_level',
  `religion` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `marital_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `phone_number` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `photo_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `default_shift_id` int NULL DEFAULT NULL COMMENT 'Link to m_shift',
  `payroll_cycle` enum('WEEKLY','MONTHLY') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'MONTHLY',
  `payroll_method` enum('TRANSFER','CASH') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `bank_account_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'no rekening',
  `bank_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'nama bank',
  `stat_confirm` tinyint UNSIGNED NULL DEFAULT 0,
  `current_department_id` bigint UNSIGNED NULL DEFAULT NULL,
  `current_section_id` bigint UNSIGNED NULL DEFAULT NULL,
  `current_position_id` bigint UNSIGNED NULL DEFAULT NULL,
  `login` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `create_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `update_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `create_by` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `update_by` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  PRIMARY KEY (`employee_id`) USING BTREE,
  UNIQUE INDEX `employee_code`(`employee_code` ASC) USING BTREE,
  INDEX `emp_type_id`(`emp_type_id` ASC) USING BTREE,
  CONSTRAINT `emp_ibfk_1` FOREIGN KEY (`emp_type_id`) REFERENCES `emp_type` (`emp_type_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 486 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Employee' ROW_FORMAT = Dynamic;

