-- ----------------------------
-- Table structure for emp_contracts
-- ----------------------------
DROP TABLE IF EXISTS `emp_contracts`;
CREATE TABLE `emp_contracts`  (
  `contract_id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Primary key unik untuk tiap kontrak kerja karyawan',
  `employee_id` bigint UNSIGNED NOT NULL COMMENT 'Relasi ke tabel emp (data karyawan)',
  `contract_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Nomor kontrak kerja (jika ada dokumen resmi)',
  `contract_type` enum('PKWT','PKWTT','INTERNSHIP','FREELANCE') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PKWT' COMMENT 'Jenis kontrak kerja: PKWT = Perjanjian Kerja Waktu Tertentu, PKWTT = Perjanjian Kerja Waktu Tidak Tertentu, Internship = Magang, Freelance = Pekerja Lepas',
  `start_date` date NOT NULL COMMENT 'Tanggal mulai berlakunya kontrak',
  `end_date` date NULL DEFAULT NULL COMMENT 'Tanggal berakhirnya kontrak (boleh null untuk PKWTT)',
  `probation_end_date` date NULL DEFAULT NULL COMMENT 'Tanggal akhir masa percobaan (umumnya 3 bulan untuk PKWTT)',
  `contract_status` enum('DRAFT','ACTIVE','EXPIRED','TERMINATED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'DRAFT' COMMENT 'Status kontrak saat ini: DRAFT, aktif, berakhir, atau dihentikan sebelum waktunya',
  `basic_salary` decimal(12, 2) NULL DEFAULT NULL COMMENT 'Gaji pokok bulanan sesuai kontrak',
  `allowance` decimal(12, 2) NULL DEFAULT NULL COMMENT 'Total tunjangan tetap (transport, makan, jabatan, dsb)',
  `overtime_rate` decimal(8, 2) NULL DEFAULT NULL COMMENT 'Tarif lembur per jam (jika diatur dalam kontrak)',
  `bpjs_ketenagakerjaan_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Nomor kepesertaan BPJS Ketenagakerjaan (jika ada)',
  `bpjs_kesehatan_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Nomor kepesertaan BPJS Kesehatan (jika ada)',
  `tax_status` enum('TK0','TK1','K0','K1','K2','K3') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Status pajak karyawan (misal: TK0, K1 sesuai status PTKP)',
  `renewal_reference_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT 'Relasi ke kontrak sebelumnya jika kontrak ini merupakan perpanjangan (renewal)',
  `document_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Link atau path ke file digital kontrak kerja (PDF / scan dokumen)',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'Catatan tambahan dari HR, seperti ketentuan khusus atau klausul tambahan',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Waktu pembuatan data kontrak',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Waktu terakhir update data kontrak',
  `created_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'User atau HR yang membuat data kontrak',
  `updated_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'User atau HR yang terakhir memperbarui data kontrak',
  PRIMARY KEY (`contract_id`) USING BTREE,
  INDEX `idx_emp_contracts_employee`(`employee_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Informasi kontrak kerja karyawan (PKWT, PKWTT, magang, dan freelance) sesuai aturan ketenagakerjaan di Indonesia' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of emp_contracts
-- ----------------------------

