  `skill_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nama keterampilan, misal: PHP, Leadership, AutoCAD',
  `skill_category` enum('TECHNICAL','SOFT','LANGUAGE','OTHER') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'TECHNICAL' COMMENT 'Jenis keterampilan: teknikal, soft skill, bahasa, dll',
  `proficiency_level` enum('BEGINNER','INTERMEDIATE','ADVANCED','EXPERT') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'BEGINNER' COMMENT 'Tingkat penguasaan',
  `years_of_experience` int NULL DEFAULT NULL COMMENT 'Lama pengalaman (dalam tahun)',
  `last_used_year` year NULL DEFAULT NULL COMMENT 'Tahun terakhir digunakan (jika relevan)',
  `certification_reference` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Nama sertifikasi atau referensi jika ada',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'Deskripsi tambahan keterampilan',
  `create_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `update_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`skill_id`) USING BTREE,
  INDEX `idx_employee`(`employee_id` ASC) USING BTREE,
  INDEX `idx_emp_skills_employee`(`employee_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Employee Skills and Competencies' ROW_FORMAT = DYNAMIC;

