-- ----------------------------
-- Table structure for tma_absence_logs_GADIPAKAI
-- ----------------------------
DROP TABLE IF EXISTS `tma_absence_logs_GADIPAKAI`;
CREATE TABLE `tma_absence_logs_GADIPAKAI`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `employee_id` int NULL DEFAULT NULL,
  `attendance_code_id` bigint NULL DEFAULT NULL COMMENT 'ID link to master attendance code Sakit/Ijin/ Alpha',
  `absence_start` datetime NULL DEFAULT NULL COMMENT 'Tanggal awal tidak masuk misal cuti melahirkan',
  `absence_stop` datetime NULL DEFAULT NULL COMMENT 'Tanggal akhir tidak masuk',
  `reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `attachment_image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `doc_status` enum('NOT_YET','WAITING','APPROVED','REJECT') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'NOT_YET',
  `auth_module` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'PR' COMMENT 'nama module misal PR atau PO atau CO',
  `current_approval_level` int UNSIGNED NULL DEFAULT 0 COMMENT 'DIproses di SC awal selalu = 0  artinya draft. \r\nsetelah di confirm ama user berubah menjadi 1. \r\nLalu jangan lupa isi filed cuurent_approval_login\r\nKalau di approve oleh level 1 maka naik berubah jadi 2.\r\ndan seterusnya\r\n Link  to m_authorize_Detail untuk melihat nama approval nya siapa\r\n',
  `current_approval_login` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Nama login yang akan melakukan approval',
  `create_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `update_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `stat_auth` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NULL DEFAULT NULL COMMENT 'DRAFT \r\nAP_1 / RJ_1\r\nAP_2 / RJ_2',
  `create_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `update_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `employee_id`(`employee_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'GA DI PAKAI Untuk mencatat cuti kapan, ijin kapan dengan approval' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tma_absence_logs_GADIPAKAI
-- ----------------------------

-- ----------------------------
-- Table structure for tma_attendance_codes
-- ----------------------------
DROP TABLE IF EXISTS `tma_attendance_codes`;
CREATE TABLE `tma_attendance_codes`  (
  `attendance_code_id` bigint NOT NULL AUTO_INCREMENT COMMENT 'Primary key kode kejadian absensi',
  `attendance_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Kode kejadian absensi (01, 02, 03, dst)',
  `attendance_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nama singkat kejadian absensi',
  `attendance_description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Deskripsi lengkap kejadian absensi',
  `effect_type` enum('NONE','DEDUCTION','BONUS','WARNING','WARNING AND DEDUCTION') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'NONE' COMMENT 'Dampak ke payroll',
  `deduction_minutes` int NULL DEFAULT 0 COMMENT 'Jumlah menit potongan keterlambatan',
  `deduction_amt` decimal(12, 2) NULL DEFAULT NULL COMMENT 'Nominal denda atau potongaan',
  `is_late` tinyint(1) NULL DEFAULT 0 COMMENT '1 = termasuk keterlambatan',
  `is_leave` tinyint(1) NULL DEFAULT 0 COMMENT '1 = termasuk izin',
  `is_absent` tinyint(1) NULL DEFAULT 0 COMMENT '1 = termasuk tidak hadir',
  `doc_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Status dokumen secara user friendly',
  `is_active` tinyint(1) NULL DEFAULT 1 COMMENT '1 aktif, 0 non aktif',
  `stat_confirm` tinyint(1) NULL DEFAULT 0 COMMENT '1 sudah dikonfirmasi',
  `stat_cancel` tinyint(1) NULL DEFAULT 0 COMMENT '1 dibatalkan',
  `stat_closed` tinyint(1) NULL DEFAULT 0 COMMENT '1 ditutup',
  `create_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Waktu pembuatan data',
  `update_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Waktu update terakhir',
  `create_by` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'User pembuat',
  `update_by` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'User pengubah terakhir',
  PRIMARY KEY (`attendance_code_id`) USING BTREE,
  UNIQUE INDEX `attendance_code`(`attendance_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Master kode kejadian absensi karyawan' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tma_attendance_codes
-- ----------------------------

