  `effect_type` enum('NONE','DEDUCTION','BONUS','WARNING','WARNING AND DEDUCTION') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'NONE' COMMENT 'Dampak ke payroll',
  `deduction_minutes` int NULL DEFAULT 0 COMMENT 'Jumlah menit potongan keterlambatan',
  `deduction_amt` decimal(12, 2) NULL DEFAULT NULL COMMENT 'Nominal denda atau potongaan',
  `deduction_percent` decimal(10, 2) NULL DEFAULT NULL COMMENT 'Percentage deduction, potongan dalam persen',
  `is_late` tinyint(1) NULL DEFAULT 0 COMMENT '1 = termasuk keterlambatan',
  `is_leave` tinyint(1) NULL DEFAULT 0 COMMENT '1 = termasuk izin',
  `is_absent` tinyint(1) NULL DEFAULT 0 COMMENT '1 = termasuk tidak hadir',
  `doc_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Status dokumen secara user friendly',
  `is_active` tinyint(1) NULL DEFAULT 1 COMMENT '1 aktif, 0 non aktif',
  `stat_confirm` tinyint(1) NULL DEFAULT 0 COMMENT '1 sudah dikonfirmasi',
  `stat_cancel` tinyint(1) NULL DEFAULT 0 COMMENT '1 dibatalkan',
  `stat_closed` tinyint(1) NULL DEFAULT 0 COMMENT '1 ditutup',
  `create_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Waktu pembuatan data',
  `update_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Waktu update terakhir',
  `create_by` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'User pembuat',
  `update_by` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'User pengubah terakhir',
  PRIMARY KEY (`attendance_code_id`) USING BTREE,
  UNIQUE INDEX `attendance_code`(`attendance_code` ASC) USING BTREE
