-- ----------------------------
-- Table structure for tma_attendance_logs
-- ----------------------------
DROP TABLE IF EXISTS `tma_attendance_logs`;
CREATE TABLE `tma_attendance_logs`  (
  `tma_logs_id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'auto number ID',
  `employee_id` bigint NULL DEFAULT NULL COMMENT 'Emp Link to emp',
  `shift_id` bigint NULL DEFAULT NULL COMMENT 'Shift',
  `period_id` bigint NULL DEFAULT NULL COMMENT 'Period Payroll',
  `device_id` bigint NULL DEFAULT NULL COMMENT 'Mesin',
  `attendance_code_id` bigint NULL DEFAULT NULL COMMENT 'ID link to master attendance code Sakit/Ijin/ Alpha',
  `work_date` date NULL DEFAULT NULL COMMENT 'tgl kerja',
  `ta_day` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Nama Hari in English',
  `ta_start` datetime NULL DEFAULT NULL COMMENT 'Jam masuk kerja',
  `ta_breakout` datetime NULL DEFAULT NULL COMMENT 'jam istirahat keluar',
  `ta_breakin` datetime NULL DEFAULT NULL COMMENT 'jam istirahat masuk',
  `ta_end` datetime NULL DEFAULT NULL COMMENT 'jam pulang kerja',
  `ta_leaveout` datetime NULL DEFAULT NULL COMMENT 'jam ijin keluar',
  `ta_leavein` datetime NULL DEFAULT NULL COMMENT 'jam ijin masuk',
  `ta_extendin` datetime NULL DEFAULT NULL COMMENT 'emergency call masuk',
  `ta_extendout` datetime NULL DEFAULT NULL COMMENT 'emergency call pulang',
  `early_overtime_duration` time NULL DEFAULT NULL COMMENT 'lembur sebelum jam masuk',
  `regular_overtime_duration` time NULL DEFAULT NULL COMMENT 'lembur sesudah jam pulang',
  `workhour_duration` time NULL DEFAULT NULL COMMENT 'durasi jam kerja \r\nRUMUSNYA \r\nta_end - ta_start - (ta_breakin - ta_breakout) - (leavein - leaveout) + (extend_out - extend_in) \r\n',
  `late_duration` time NULL DEFAULT NULL COMMENT 'menghitung total durasi terlambat',
  `break_late_duration` time NULL DEFAULT NULL COMMENT 'menghitung total durasi terlambat istirahat',
  `leave_duration` time NULL DEFAULT NULL COMMENT 'menghitung total durasi izin',
  `stat_normal` tinyint UNSIGNED NULL DEFAULT NULL COMMENT 'Status Normal 1 = normal 0 = not normal',
  `stat_present` tinyint UNSIGNED NULL DEFAULT NULL COMMENT '1 = present 0 = absence',
  `stat_overtime` tinyint UNSIGNED NULL DEFAULT 0,
  `stat_late_under_5min` tinyint UNSIGNED NULL DEFAULT 0 COMMENT 'telat dibawah 5 menit',
  `stat_late_over_5min` tinyint UNSIGNED NULL DEFAULT 0 COMMENT 'telat diatas 5 menit',
  `overtime_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'tipe overtime diisi WORKDAY, HOLIDAY, SUNDAY',
  `is_finger` tinyint NULL DEFAULT NULL COMMENT 'untuk cek apakah karyawan tsb finger apa tidak',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `create_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `update_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `create_by` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `update_by` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  PRIMARY KEY (`tma_logs_id`) USING BTREE,
  UNIQUE INDEX `employee_id_2`(`employee_id` ASC, `period_id` ASC, `device_id` ASC, `work_date` ASC) USING BTREE,
  INDEX `office_id_in`(`ta_start` ASC) USING BTREE,
  INDEX `office_id_out`(`ta_end` ASC) USING BTREE,
  INDEX `employee_id`(`employee_id` ASC) USING BTREE,
  INDEX `shift_id`(`shift_id` ASC) USING BTREE,
  INDEX `attendance_code_id`(`attendance_code_id` ASC) USING BTREE,
  CONSTRAINT `tma_attendance_logs_ibfk_1` FOREIGN KEY (`attendance_code_id`) REFERENCES `tma_attendance_codes` (`attendance_code_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 7585 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'MAIN TABLE kunci data absensi' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tma_attendance_logs
-- ----------------------------

-- ----------------------------
-- Table structure for tma_attendance_summary
-- ----------------------------
DROP TABLE IF EXISTS `tma_attendance_summary`;
CREATE TABLE `tma_attendance_summary`  (
  `summary_id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID this document',
  `employee_id` bigint NOT NULL COMMENT 'Employee yang akan digaji',
  `period_id` bigint NOT NULL COMMENT 'FK payroll_periods, SATU-SATUNYA referensi periode payroll',
  `workday_days` int NULL DEFAULT 0 COMMENT 'Jumlah hari kerja efektif dalam periode (validasi bonus & audit)',
  `late_under_5_count` int NULL DEFAULT 0 COMMENT 'Payroll Rule P1: frekuensi telat <= 5 menit',
  `late_under_5_minutes` int NULL DEFAULT 0 COMMENT 'Payroll Rule P1: total menit telat <= 5 menit',
  `late_over_5_count` int NULL DEFAULT 0 COMMENT 'Payroll Rule P1: frekuensi telat > 5 menit',
  `late_over_5_minutes` int NULL DEFAULT 0 COMMENT 'Payroll Rule P1: total menit telat > 5 menit',
  `early_out_days` int NULL DEFAULT 0 COMMENT 'Payroll Rule P1: jumlah hari pulang lebih awal',
  `early_out_minutes` int NULL DEFAULT 0 COMMENT 'Payroll Rule P1: total menit pulang lebih awal',
  `break_in_late_count` int NULL DEFAULT NULL COMMENT 'total telat setelah istirahat',
  `overtime_workday_days` int NULL DEFAULT NULL COMMENT 'Rule Payroll: jumlah hari lembur di hari kerja',
  `overtime_workday_hours` decimal(8, 2) NULL DEFAULT 0.00 COMMENT 'Payroll Rule P2: jam lembur hari kerja',
  `overtime_holiday_days` int NULL DEFAULT NULL COMMENT 'Rule Payroll: jumlah hari lembur di hari libur/minggu',
  `overtime_holiday_hours` decimal(8, 2) NULL DEFAULT 0.00 COMMENT 'Payroll Rule P2: jam lembur hari libur/minggu',
  `emergency_call_hours` decimal(8, 2) NULL DEFAULT NULL COMMENT 'Emergency Call dalam jam',
  `present_days` int NULL DEFAULT NULL COMMENT 'Hari hadir valid (dipakai bonus kehadiran)',
  `absent_days` int NULL DEFAULT NULL COMMENT 'Hari absen tanpa keterangan (pengurang payroll)',
  `sick_days` int NULL DEFAULT NULL COMMENT 'Hari sakit resmi (sesuai kebijakan perusahaan)',
  `leave_days` int NULL DEFAULT NULL COMMENT 'Hari ijin resmi (cuti)',
  `acknowledged_count` int NULL DEFAULT NULL COMMENT 'Total izin mengetahui',
  `approved_leave_count` int NULL DEFAULT NULL COMMENT 'Total izin menyetujui',
  `dayoff_days` int NULL DEFAULT NULL COMMENT 'Hari libur mingguan',
  `holiday_days` int NULL DEFAULT NULL COMMENT 'Hari libur nasional',
  `anomaly_days` int NULL DEFAULT 0 COMMENT 'Hari absensi tidak valid → payroll harus HOLD',
  `anomaly_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'Catatan koreksi manual HR atas anomali',
  `disciplinary_points` int NULL DEFAULT 0 COMMENT 'Akumulasi poin pelanggaran disiplin (basis SP)',
  `payroll_ready` tinyint NULL DEFAULT 0 COMMENT '1 = boleh digaji, 0 = HOLD payroll',
  `create_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `create_by` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `update_by` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `update_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`summary_id`) USING BTREE,
  UNIQUE INDEX `uq_employee_period`(`employee_id` ASC, `period_id` ASC) USING BTREE,
  INDEX `idx_payroll_period`(`period_id` ASC) USING BTREE,
  INDEX `idx_payroll_ready`(`payroll_ready` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1227 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'Table summary buat summary absensi' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tma_attendance_summary
-- ----------------------------

-- ----------------------------
-- Table structure for tma_discipline_log
-- ----------------------------
DROP TABLE IF EXISTS `tma_discipline_log`;
CREATE TABLE `tma_discipline_log`  (
  `discipline_id` bigint NOT NULL AUTO_INCREMENT,
  `employee_id` bigint UNSIGNED NOT NULL COMMENT 'Referensi karyawan',
  `discipline_type` enum('VERBAL','SP1','SP2','SP3') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Jenis tindakan disiplin',
  `violation_date` date NOT NULL COMMENT 'Tanggal terjadinya pelanggaran',
  `violation_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Kode pelanggaran (mis: LATE, ABSENT, NO_SAFETY)',
  `violation_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'Deskripsi pelanggaran',
  `verbal_sequence` int NULL DEFAULT NULL COMMENT 'Urutan verbal warning (1–6), hanya untuk VERBAL',
  `impact_salary` tinyint(1) NULL DEFAULT 0 COMMENT 'Apakah berdampak ke gaji',
  `reference_leave_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT 'Referensi ke izin/cuti jika relevan',
  `doc_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Status dokumen versi user',
  `is_active` tinyint(1) NULL DEFAULT 1,
  `stat_confirm` tinyint(1) NULL DEFAULT 0,
  `stat_cancel` tinyint(1) NULL DEFAULT 0,
  `stat_closed` tinyint(1) NULL DEFAULT 0,
  `create_log` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `update_log` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `create_by` bigint UNSIGNED NULL DEFAULT NULL,
  `update_by` bigint UNSIGNED NULL DEFAULT NULL,
  PRIMARY KEY (`discipline_id`) USING BTREE,
  INDEX `fk_violation`(`violation_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Log pelanggaran dan sanksi kedisiplinan karyawan' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of tma_discipline_log
-- ----------------------------

-- ----------------------------
-- Table structure for tma_leave_quota
