  `employee_id` bigint UNSIGNED NOT NULL,
  `leave_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `quota_year` year NOT NULL,
  `quota_total` int NULL DEFAULT 0,
  `quota_used` int NULL DEFAULT 0,
  `quota_remaining` int GENERATED ALWAYS AS ((`quota_total` - `quota_used`)) STORED NULL,
  `quota_expireddate` date NULL DEFAULT NULL,
  `create_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `update_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `create_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `update_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uq_emp_year_type`(`employee_id` ASC, `quota_year` ASC, `leave_type` ASC) USING BTREE,
  INDEX `idx_leavequota_employee`(`employee_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Lookup simpan sisa cuti' ROW_FORMAT = Dynamic;

