-- ----------------------------
-- Table structure for tma_leave_request
-- ----------------------------
DROP TABLE IF EXISTS `tma_leave_request`;
CREATE TABLE `tma_leave_request`  (
  `leave_id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Primary key permohonan cuti/izin/sakit',
  `employee_id` bigint UNSIGNED NOT NULL COMMENT 'Referensi ke master karyawan',
  `request_date` date NOT NULL COMMENT 'Tanggal pengajuan permohonan (bisa jauh sebelum tanggal izin/cuti)',
  `leave_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Jenis permohonan',
  `start_date` date NULL DEFAULT NULL COMMENT 'Tanggal mulai',
  `start_time` time NULL DEFAULT NULL COMMENT 'Jam mulai izin (khusus leave_type = IJIN)',
  `end_time` time NULL DEFAULT NULL COMMENT 'Jam selesai izin (khusus leave_type = IJIN)',
  `end_date` date NULL DEFAULT NULL COMMENT 'Tanggal selesai',
  `total_days` decimal(5, 2) NULL DEFAULT NULL COMMENT 'Total hari (support 0.5 hari)',
  `reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'Alasan pengajuan',
  `doctor_letter_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Path file surat dokter (wajib jika SAKIT)',
  `doctor_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Nama dokter',
  `hospital_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Nama RS/Klinik',
  `stat_auth` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'DRAFT' COMMENT 'Status approval: DRAFT, AP_1, RJ_1, AP_2, RJ_2',
  `current_approval_login` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Login user yang sedang memegang approval',
  `current_approval_level` int NULL DEFAULT 0 COMMENT 'Level approval SC (0=draft)',
  `next_approval_login` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Login user approval berikutnya',
  `doc_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Status dokumen versi user (Menunggu Atasan, HR, Disetujui, dll)',
  `is_active` tinyint(1) NULL DEFAULT 1 COMMENT 'Status aktif data',
  `stat_confirm` tinyint(1) NULL DEFAULT 0 COMMENT 'Flag konfirmasi',
  `stat_cancel` tinyint(1) NULL DEFAULT 0 COMMENT 'Flag pembatalan',
  `stat_closed` tinyint(1) NULL DEFAULT 0 COMMENT 'Flag closed',
  `create_log` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Waktu pembuatan',
  `update_log` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Waktu update',
  `create_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'User pembuat',
  `update_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'User terakhir update',
  PRIMARY KEY (`leave_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Permohonan cuti, izin, dan sakit (Time Management Attendance)' ROW_FORMAT = Dynamic;

