-- ----------------------------
-- View structure for v1_attendance_log
-- ----------------------------
DROP VIEW IF EXISTS `v1_attendance_log`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v1_attendance_log` AS select `l`.`tma_logs_id` AS `tma_logs_id`,`l`.`employee_id` AS `employee_id`,`e`.`employee_code` AS `employee_code`,`e`.`full_name` AS `full_name`,`l`.`period_id` AS `period_id`,`p`.`payroll_code` AS `payroll_code`,`p`.`payroll_cycle` AS `payroll_cycle`,`l`.`work_date` AS `work_date`,`l`.`ta_day` AS `ta_day`,`l`.`shift_id` AS `shift_id`,`s`.`shift_name` AS `shift_name`,`l`.`device_id` AS `device_id`,`l`.`ta_start` AS `ta_start`,`l`.`ta_breakout` AS `ta_breakout`,`l`.`ta_breakin` AS `ta_breakin`,`l`.`ta_end` AS `ta_end`,`l`.`ta_leaveout` AS `ta_leaveout`,`l`.`ta_leavein` AS `ta_leavein`,`l`.`ta_extendin` AS `ta_extendin`,`l`.`ta_extendout` AS `ta_extendout`,`l`.`workhour_duration` AS `workhour_duration`,`l`.`leave_duration` AS `leave_duration`,`l`.`late_duration` AS `late_duration`,`l`.`break_late_duration` AS `break_late_duration`,`l`.`early_overtime_duration` AS `early_overtime_duration`,`l`.`regular_overtime_duration` AS `regular_overtime_duration`,`l`.`overtime_type` AS `overtime_type`,`l`.`attendance_code_id` AS `attendance_code_id`,`ac`.`attendance_code` AS `attendance_code`,`ac`.`attendance_name` AS `attendance_name`,`l`.`stat_present` AS `stat_present`,`l`.`stat_normal` AS `stat_normal`,`l`.`stat_overtime` AS `stat_overtime`,`l`.`stat_late_under_5min` AS `stat_late_under_5min`,`l`.`stat_late_over_5min` AS `stat_late_over_5min`,(case when (`ac`.`attendance_name` is not null) then `ac`.`attendance_name` when (`l`.`stat_late_over_5min` = 1) then 'Terlambat > 5 Menit' when (`l`.`stat_late_under_5min` = 1) then 'Terlambat < 5 Menit' when (`l`.`stat_overtime` = 1) then 'Lembur' when (`l`.`stat_present` = 1) then 'Hadir' else 'Belum Diproses' end) AS `attendance_status`,(case when (`ac`.`attendance_code` = 'AL') then 'ABSENT' when (`ac`.`attendance_code` in ('SC1','SC2','SC3')) then 'SAKIT' when (`ac`.`attendance_code` = 'CT') then 'CUTI' when (`ac`.`attendance_code` in ('03','04','05')) then 'IZIN' when ((`l`.`stat_late_under_5min` = 1) or (`l`.`stat_late_over_5min` = 1)) then 'LATE' when (`l`.`stat_present` = 1) then 'PRESENT' else 'UNKNOWN' end) AS `attendance_group`,`l`.`note` AS `note`,`l`.`create_log` AS `create_log`,`l`.`update_log` AS `update_log`,`l`.`create_by` AS `create_by`,`l`.`update_by` AS `update_by` from ((((`tma_attendance_logs` `l` join `emp` `e` on((`e`.`employee_id` = `l`.`employee_id`))) left join `tmpyr`.`payroll_periods` `p` on((`p`.`period_id` = `l`.`period_id`))) left join `tmmst`.`m_shifts` `s` on((`s`.`shift_id` = `l`.`shift_id`))) left join `tma_attendance_codes` `ac` on((`ac`.`attendance_code_id` = `l`.`attendance_code_id`)));

-- ----------------------------
-- View structure for v1_attendance_report
-- ----------------------------
DROP VIEW IF EXISTS `v1_attendance_report`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v1_attendance_report` AS select `c`.`period_id` AS `period_id`,`c`.`payroll_code` AS `payroll_code`,`c`.`payroll_cycle` AS `payroll_cycle`,`c`.`work_date` AS `work_date`,`es`.`employee_id` AS `employee_id`,`es`.`employee_code` AS `employee_code`,`es`.`full_name` AS `full_name`,`es`.`shift_id` AS `shift_id`,`es`.`shift_name` AS `shift_name`,`al`.`tma_logs_id` AS `tma_logs_id`,`al`.`device_id` AS `device_id`,`al`.`ta_start` AS `ta_start`,`al`.`ta_breakout` AS `ta_breakout`,`al`.`ta_breakin` AS `ta_breakin`,`al`.`ta_end` AS `ta_end`,`al`.`workhour_duration` AS `workhour_duration`,`al`.`leave_duration` AS `leave_duration`,`al`.`late_duration` AS `late_duration`,`al`.`break_late_duration` AS `break_late_duration`,`al`.`attendance_code` AS `attendance_code`,`al`.`attendance_name` AS `attendance_name`,(case when (`al`.`tma_logs_id` is null) then 'Alpha' else `al`.`attendance_status` end) AS `attendance_status`,(case when (`al`.`tma_logs_id` is null) then 'ABSENT' else `al`.`attendance_group` end) AS `attendance_group`,`al`.`note` AS `note`,`al`.`create_log` AS `create_log`,`al`.`update_log` AS `update_log` from ((`v1_employee_shift` `es` join `v1_calendar_payroll` `c`) left join `v1_attendance_log` `al` on(((`al`.`employee_id` = `es`.`employee_id`) and (`al`.`period_id` = `c`.`period_id`) and (`al`.`work_date` = `c`.`work_date`)))) where ((`al`.`tma_logs_id` is null) or (`al`.`attendance_group` = 'LATE')) order by `c`.`work_date` desc,`es`.`full_name`;

-- ----------------------------
-- View structure for v1_calendar_payroll
-- ----------------------------
DROP VIEW IF EXISTS `v1_calendar_payroll`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v1_calendar_payroll` AS select `p`.`period_id` AS `period_id`,`p`.`payroll_code` AS `payroll_code`,`p`.`payroll_cycle` AS `payroll_cycle`,(`p`.`start_date` + interval `n`.`num` day) AS `work_date` from (`tmpyr`.`payroll_periods` `p` join (select 0 AS `num` union all select 1 AS `1` union all select 2 AS `2` union all select 3 AS `3` union all select 4 AS `4` union all select 5 AS `5` union all select 6 AS `6` union all select 7 AS `7` union all select 8 AS `8` union all select 9 AS `9` union all select 10 AS `10` union all select 11 AS `11` union all select 12 AS `12` union all select 13 AS `13` union all select 14 AS `14` union all select 15 AS `15` union all select 16 AS `16` union all select 17 AS `17` union all select 18 AS `18` union all select 19 AS `19` union all select 20 AS `20` union all select 21 AS `21` union all select 22 AS `22` union all select 23 AS `23` union all select 24 AS `24` union all select 25 AS `25` union all select 26 AS `26` union all select 27 AS `27` union all select 28 AS `28` union all select 29 AS `29` union all select 30 AS `30` union all select 31 AS `31`) `n`) where ((`p`.`is_active` = 1) and ((`p`.`start_date` + interval `n`.`num` day) <= `p`.`end_date`));

-- ----------------------------
-- View structure for v1_emp_leave_balance
-- ----------------------------
DROP VIEW IF EXISTS `v1_emp_leave_balance`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v1_emp_leave_balance` AS select `m`.`employee_id` AS `employee_id`,`m`.`full_name` AS `full_name`,`q`.`leave_type` AS `leave_type`,`q`.`quota_year` AS `quota_year`,`q`.`quota_total` AS `quota_total`,`q`.`quota_used` AS `quota_used`,`q`.`quota_remaining` AS `quota_remaining` from (`tmmst`.`m_emp` `m` left join `tma_leave_quota` `q` on((`q`.`employee_id` = `m`.`employee_id`))) where ((`q`.`quota_year` = year(curdate())) and (`q`.`leave_type` = 'CUTI'));

-- ----------------------------
-- View structure for v1_employee_shift
-- ----------------------------
DROP VIEW IF EXISTS `v1_employee_shift`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v1_employee_shift` AS select `e`.`employee_id` AS `employee_id`,`e`.`employee_code` AS `employee_code`,`e`.`full_name` AS `full_name`,`e`.`default_shift_id` AS `default_shift_id`,coalesce(`a`.`shift_dst_id`,`e`.`default_shift_id`) AS `shift_id`,`s`.`shift_name` AS `shift_name`,`a`.`assignment_type` AS `assignment_type`,`a`.`period_id` AS `period_id`,(case when (`a`.`sa_id` is null) then 'DEFAULT SHIFT' else 'CHANGE SHIFT' end) AS `shift_source` from ((`emp` `e` left join (select `d`.`employee_id` AS `employee_id`,`a`.`sa_id` AS `sa_id`,`a`.`period_id` AS `period_id`,`a`.`shift_dst_id` AS `shift_dst_id`,`a`.`assignment_type` AS `assignment_type` from ((`tma_so_ass` `a` join `tma_so_ass_detail` `d` on((`d`.`sa_id` = `a`.`sa_id`))) join `tmpyr`.`payroll_periods` `pp` on(((`pp`.`period_id` = `a`.`period_id`) and (`pp`.`is_active` = 1)))) where (`a`.`sa_id` = (select max(`a2`.`sa_id`) from ((`tma_so_ass` `a2` join `tma_so_ass_detail` `d2` on((`d2`.`sa_id` = `a2`.`sa_id`))) join `tmpyr`.`payroll_periods` `pp2` on(((`pp2`.`period_id` = `a2`.`period_id`) and (`pp2`.`is_active` = 1)))) where (`d2`.`employee_id` = `d`.`employee_id`)))) `a` on((`a`.`employee_id` = `e`.`employee_id`))) left join `tmmst`.`m_shifts` `s` on((`s`.`shift_id` = coalesce(`a`.`shift_dst_id`,`e`.`default_shift_id`)))) where (`e`.`is_active` = 1);

-- ----------------------------
-- View structure for v1_m_constant
-- ----------------------------
DROP VIEW IF EXISTS `v1_m_constant`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v1_m_constant` AS select `tmmst`.`m_constant`.`id` AS `id`,`tmmst`.`m_constant`.`constant_string` AS `constant_string`,`tmmst`.`m_constant`.`constant_number` AS `constant_number`,`tmmst`.`m_constant`.`constant_type` AS `constant_type`,`tmmst`.`m_constant`.`remark` AS `remark`,`tmmst`.`m_constant`.`update_log` AS `update_log`,`tmmst`.`m_constant`.`create_log` AS `create_log` from `tmmst`.`m_constant`;

-- ----------------------------
-- View structure for v1_m_emp_dept
-- ----------------------------
DROP VIEW IF EXISTS `v1_m_emp_dept`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v1_m_emp_dept` AS select `m`.`employee_id` AS `employee_id`,`m`.`employee_code` AS `employee_code`,`m`.`full_name` AS `full_name`,`m`.`is_active` AS `is_active`,`m`.`payroll_cycle` AS `payroll_cycle`,`pi`.`payroll_method` AS `payroll_method`,`d`.`current_department_id` AS `current_department_id`,`d`.`current_position_id` AS `current_position_id`,`od`.`department_name` AS `department_name`,concat(`m`.`full_name`,' | ',coalesce(`od`.`department_name`,'-')) AS `empdept` from (((`tmmst`.`m_emp` `m` left join `emp_detail` `d` on((`d`.`employee_id` = `m`.`employee_id`))) left join `tmpyr`.`emp_payment_info` `pi` on((`pi`.`employee_id` = `m`.`employee_id`))) left join `tmmst`.`org_department` `od` on((`od`.`department_id` = `d`.`current_department_id`))) where (`m`.`is_active` = 1);

-- ----------------------------
-- View structure for v1_m_machine
-- ----------------------------
DROP VIEW IF EXISTS `v1_m_machine`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v1_m_machine` AS select `tmmst`.`m_machine`.`machine_id` AS `machine_id`,`tmmst`.`m_machine`.`machine_name` AS `machine_name`,`tmmst`.`m_machine`.`stat_machine` AS `stat_machine`,`tmmst`.`m_machine`.`process_id_default` AS `process_id_default`,`tmmst`.`m_machine`.`employee_id` AS `employee_id`,`tmmst`.`m_machine`.`login_name` AS `login_name`,`tmmst`.`m_machine`.`gantt_color` AS `gantt_color`,`tmmst`.`m_machine`.`is_active` AS `is_active`,`tmmst`.`m_machine`.`notes` AS `notes`,`tmmst`.`m_machine`.`create_by` AS `create_by`,`tmmst`.`m_machine`.`update_by` AS `update_by`,`tmmst`.`m_machine`.`create_log` AS `create_log`,`tmmst`.`m_machine`.`update_log` AS `update_log` from `tmmst`.`m_machine` where (`tmmst`.`m_machine`.`is_active` = 1);

-- ----------------------------
-- View structure for v1_m_shift
-- ----------------------------
DROP VIEW IF EXISTS `v1_m_shift`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v1_m_shift` AS select `s`.`shift_id` AS `shift_id`,`s`.`shift_name` AS `shift_name`,`s`.`emp_type_id` AS `emp_type_id`,`s`.`description` AS `description`,`s`.`is_active` AS `is_active`,`s`.`create_log` AS `create_log`,`s`.`update_log` AS `update_log`,`s`.`create_by` AS `create_by`,`s`.`update_by` AS `update_by` from `tmmst`.`m_shifts` `s` where (`s`.`is_active` = 1);

-- ----------------------------
-- View structure for v1_m_shift_details
-- ----------------------------
DROP VIEW IF EXISTS `v1_m_shift_details`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v1_m_shift_details` AS select `sd`.`shift_detail_id` AS `shift_detail_id`,`sd`.`shift_id` AS `shift_id`,`sd`.`shift_day` AS `shift_day`,`sd`.`start_time` AS `start_time`,`sd`.`break_out` AS `break_out`,`sd`.`break_in` AS `break_in`,`sd`.`end_time` AS `end_time`,`sd`.`description` AS `description`,`sd`.`create_log` AS `create_log`,`sd`.`update_log` AS `update_log`,`sd`.`create_by` AS `create_by`,`sd`.`update_by` AS `update_by` from `tmmst`.`m_shifts_details` `sd`;

-- ----------------------------
-- View structure for v1_payroll_period_act
-- ----------------------------
DROP VIEW IF EXISTS `v1_payroll_period_act`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v1_payroll_period_act` AS select `pp`.`period_id` AS `period_id`,`pp`.`payroll_code` AS `payroll_code`,`pp`.`payroll_cycle` AS `payroll_cycle`,`pp`.`start_date` AS `start_date`,`pp`.`end_date` AS `end_date`,`pp`.`period_year` AS `period_year`,`pp`.`period_month` AS `period_month`,`pp`.`payment_date` AS `payment_date`,`pp`.`is_active` AS `is_active`,`pp`.`stat_confirm` AS `stat_confirm`,`pp`.`stat_closed` AS `stat_closed`,`pp`.`remarks` AS `remarks`,`pp`.`create_log` AS `create_log`,`pp`.`update_log` AS `update_log`,`pp`.`create_by` AS `create_by`,`pp`.`update_by` AS `update_by` from `tmpyr`.`payroll_periods` `pp` where (`pp`.`is_active` = 1);

-- ----------------------------
-- View structure for v1_tma_attd_logs
-- ----------------------------
DROP VIEW IF EXISTS `v1_tma_attd_logs`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v1_tma_attd_logs` AS select `at`.`tma_logs_id` AS `tma_logs_id`,`at`.`employee_id` AS `employee_id`,`at`.`shift_id` AS `shift_id`,`at`.`period_id` AS `period_id`,`at`.`device_id` AS `device_id`,`at`.`ta_start` AS `ta_start`,`at`.`ta_breakout` AS `ta_breakout`,`at`.`ta_breakin` AS `ta_breakin`,`at`.`ta_end` AS `ta_end`,`at`.`ta_day` AS `ta_day`,`at`.`ta_extendin` AS `ta_extendin`,`at`.`ta_extendout` AS `ta_extendout`,`at`.`ta_leaveout` AS `ta_leaveout`,`at`.`ta_leavein` AS `ta_leavein`,`at`.`workhour_duration` AS `workhour_duration`,`at`.`stat_normal` AS `stat_normal`,`at`.`stat_present` AS `stat_present`,`at`.`attendance_code_id` AS `attendance_code_id`,`at`.`note` AS `note`,`at`.`create_log` AS `create_log`,`at`.`update_log` AS `update_log`,`at`.`create_by` AS `create_by`,`at`.`update_by` AS `update_by` from (`tma_attendance_logs` `at` join `tmpyr`.`payroll_periods` `pr` on((`pr`.`period_id` = `at`.`period_id`))) where (`pr`.`is_active` = 1);

-- ----------------------------
-- Procedure structure for sp_attendance_exception_report
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_attendance_exception_report`;
delimiter ;;
CREATE PROCEDURE `sp_attendance_exception_report`()
BEGIN

WITH RECURSIVE active_period AS
(
    SELECT
        period_id,
        payroll_code,
        payroll_cycle,
        start_date,
        end_date
    FROM tmpyr.payroll_periods
    WHERE is_active = 1
    LIMIT 1
),

calendar AS
(
    SELECT
        start_date AS work_date
    FROM active_period

    UNION ALL

    SELECT
        DATE_ADD(work_date,INTERVAL 1 DAY)
    FROM calendar
    WHERE work_date <
    (
        SELECT end_date
        FROM active_period
    )
),

emp_shift AS
(
    SELECT

        e.employee_id,
        e.employee_code,
        e.full_name,

        COALESCE
        (
            (
                SELECT sa.shift_dst_id
                FROM tmhrm.tma_so_ass sa
                WHERE FIND_IN_SET(
										CONVERT(CAST(e.employee_id AS CHAR) USING utf8mb4)
												COLLATE utf8mb4_unicode_ci,
										REPLACE(sa.group_emp_id,';',',')
								) > 0
                ORDER BY sa.sa_id DESC
                LIMIT 1
            ),
            e.default_shift_id
        ) AS shift_id

    FROM tmhrm.emp e
    WHERE e.is_active = 1
),

attendance_base AS
(
    SELECT

        c.work_date,

        p.period_id,
        p.payroll_code,
        p.payroll_cycle,

        e.employee_id,
        e.employee_code,
        e.full_name,

        e.shift_id,

        s.shift_name,

        sd.start_time,
        sd.break_out,
        sd.break_in,
        sd.end_time,

        l.tma_logs_id,
        l.device_id,

        l.ta_start,
        l.ta_breakout,
        l.ta_breakin,
        l.ta_end,

        l.workhour_duration,
        l.leave_duration,
        l.late_duration,
        l.break_late_duration,

        l.early_overtime_duration,
        l.regular_overtime_duration,

        l.stat_present,
        l.stat_normal,
        l.stat_overtime,
        l.stat_late_under_5min,
        l.stat_late_over_5min,

        l.attendance_code_id,

        ac.attendance_code,
        ac.attendance_name,

        l.note,

        l.create_log,
        l.update_log

    FROM calendar c

    CROSS JOIN emp_shift e

    CROSS JOIN active_period p

    LEFT JOIN tmmst.m_shifts s
        ON s.shift_id = e.shift_id

    LEFT JOIN tmmst.m_shifts_details sd
        ON sd.shift_id = e.shift_id
       AND UPPER(sd.shift_day)=UPPER(DAYNAME(c.work_date))

    LEFT JOIN tmhrm.tma_attendance_logs l
        ON l.employee_id=e.employee_id
       AND l.period_id=p.period_id
       AND l.work_date=c.work_date

    LEFT JOIN tmhrm.tma_attendance_codes ac
        ON ac.attendance_code_id=l.attendance_code_id
)

SELECT

    period_id,
    payroll_code,
    payroll_cycle,

    employee_id,
    employee_code,
    full_name,

    work_date,

    shift_id,
    shift_name,

    start_time,
    break_out,
    break_in,
    end_time,

    device_id,

    ta_start,
    ta_breakout,
    ta_breakin,
    ta_end,

    workhour_duration,
    leave_duration,
    late_duration,
    break_late_duration,

    early_overtime_duration,
    regular_overtime_duration,

    attendance_code,
    attendance_name,

    stat_present,
    stat_normal,
    stat_overtime,
    stat_late_under_5min,
    stat_late_over_5min,

    CASE

        WHEN start_time IS NULL
        THEN 'Libur'

        WHEN tma_logs_id IS NULL
        THEN 'Alpha'

        WHEN attendance_code IS NOT NULL
        THEN attendance_name

        WHEN stat_late_over_5min = 1
        THEN 'Terlambat > 5 Menit'

        WHEN stat_late_under_5min = 1
        THEN 'Terlambat < 5 Menit'

        WHEN stat_overtime = 1
        THEN 'Lembur'

        WHEN stat_present = 1
        THEN 'Hadir'

        ELSE 'Unknown'

    END AS attendance_status,

    CASE

        WHEN start_time IS NULL
        THEN 'OFF'

        WHEN tma_logs_id IS NULL
        THEN 'ABSENT'

        WHEN attendance_code='al'
        THEN 'ABSENT'

        WHEN attendance_code IN ('sc1','sc2','sc3')
        THEN 'SAKIT'

        WHEN attendance_code='ct'
        THEN 'CUTI'

        WHEN attendance_code IN ('03','04','05')
        THEN 'IZIN'

        WHEN stat_late_under_5min=1
          OR stat_late_over_5min=1
        THEN 'LATE'

        ELSE 'PRESENT'

    END AS attendance_group,

    note,

    create_log,
    update_log

FROM attendance_base

WHERE start_time IS NOT NULL

ORDER BY
    work_date DESC,
    full_name ASC;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for sp_patch_att_summ_by_emp
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_patch_att_summ_by_emp`;
delimiter ;;
CREATE PROCEDURE `sp_patch_att_summ_by_emp`(IN p_period_id BIGINT,
    IN p_employee_id BIGINT)
  COMMENT 'fungsi ini dipanggil untuk trigger'
proc_main: BEGIN

    DECLARE v_period_id BIGINT;
    DECLARE v_start_date DATE;
    DECLARE v_end_date DATE;
    DECLARE v_payroll_cycle ENUM('WEEKLY','MONTHLY');
    DECLARE v_workday_days INT;
    DECLARE v_dayoff_days INT;
    DECLARE v_holiday_days INT;

    SET v_period_id = p_period_id;

    SELECT period_id, start_date, end_date, payroll_cycle
    INTO v_period_id, v_start_date, v_end_date, v_payroll_cycle
    FROM tmpyr.payroll_periods
    WHERE period_id = v_period_id
      AND is_active = 1
      AND stat_closed = 0;

    -- =========================
    -- HITUNG SUNDAY
    -- =========================
    SELECT COUNT(*)
    INTO v_dayoff_days
    FROM (
        SELECT DATE_ADD(v_start_date, INTERVAL seq DAY) AS work_date
        FROM (
            SELECT 0 seq UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL
            SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL
            SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL
            SELECT 12 UNION ALL SELECT 13 UNION ALL SELECT 14 UNION ALL SELECT 15 UNION ALL
            SELECT 16 UNION ALL SELECT 17 UNION ALL SELECT 18 UNION ALL SELECT 19 UNION ALL
            SELECT 20 UNION ALL SELECT 21 UNION ALL SELECT 22 UNION ALL SELECT 23 UNION ALL
            SELECT 24 UNION ALL SELECT 25 UNION ALL SELECT 26 UNION ALL SELECT 27 UNION ALL
            SELECT 28 UNION ALL SELECT 29 UNION ALL SELECT 30
        ) x
        WHERE DATE_ADD(v_start_date, INTERVAL seq DAY) <= v_end_date
    ) d
    WHERE DAYNAME(d.work_date) = 'Sunday';

    -- =========================
    -- HITUNG HOLIDAY
    -- =========================
    SELECT COUNT(*)
    INTO v_holiday_days
    FROM tmmst.m_holidays h
    WHERE h.date BETWEEN v_start_date AND v_end_date;

    -- =========================
    -- HITUNG WORKDAY
    -- =========================
    SELECT COUNT(*)
    INTO v_workday_days
    FROM (
        SELECT DATE_ADD(v_start_date, INTERVAL seq DAY) AS work_date
        FROM (
            SELECT 0 seq UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL
            SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL
            SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL
            SELECT 12 UNION ALL SELECT 13 UNION ALL SELECT 14 UNION ALL SELECT 15 UNION ALL
            SELECT 16 UNION ALL SELECT 17 UNION ALL SELECT 18 UNION ALL SELECT 19 UNION ALL
            SELECT 20 UNION ALL SELECT 21 UNION ALL SELECT 22 UNION ALL SELECT 23 UNION ALL
            SELECT 24 UNION ALL SELECT 25 UNION ALL SELECT 26 UNION ALL SELECT 27 UNION ALL
            SELECT 28 UNION ALL SELECT 29 UNION ALL SELECT 30
        ) x
        WHERE DATE_ADD(v_start_date, INTERVAL seq DAY) <= v_end_date
    ) d
    WHERE DAYNAME(d.work_date) <> 'Sunday'
      AND NOT EXISTS (
            SELECT 1
            FROM tmmst.m_holidays h
            WHERE h.date = d.work_date
      );

    -- =========================
    -- INSERT / UPDATE SUMMARY
    -- =========================
            employee_id,
            period_id,
            workday_days,
						dayoff_days,
						holiday_days,
            late_under_5_count,
            late_under_5_minutes,
            late_over_5_count,
            late_over_5_minutes,
            early_out_days,
            early_out_minutes,
						break_in_late_count,
            overtime_workday_days,
            overtime_workday_hours,
            overtime_holiday_days,
            overtime_holiday_hours,
            present_days,
            absent_days,
            sick_days,
						leave_days,
						acknowledged_count,
						approved_leave_count,
						emergency_call_hours
        )
        SELECT
            l.employee_id,
            v_period_id,
            v_workday_days,
						v_dayoff_days,
						v_holiday_days,
						
            -- Telat < 5 menit
						COUNT(DISTINCT
								CASE
										WHEN l.late_min > 0 AND l.late_min < 5
										THEN l.work_date
								END
						),

						SUM(CASE WHEN l.late_min > 0 AND l.late_min < 5 THEN l.late_min ELSE 0 END),


            -- Telat >= 5 menit
						COUNT(DISTINCT 
								CASE 
										WHEN late_min >= 5
										THEN DATE(work_date)
								END
						),
						SUM(CASE WHEN l.late_min >= 5 THEN l.late_min ELSE 0 END),

            -- Pulang cepat
            COUNT(DISTINCT
								CASE
										WHEN l.early_out_min > 0
										THEN l.work_date
								END
						),
            SUM(CASE WHEN l.early_out_min > 0 THEN l.early_out_min ELSE 0 END),

						-- Break In Late Count
						COUNT(DISTINCT
								CASE
										WHEN l.break_late_duration IS NOT NULL
										 AND l.break_late_duration <> '00:00:00'
										THEN l.work_date
								END
						),
            -- Lembur hari kerja (harus ada SO)
            COUNT(DISTINCT
                CASE
                    WHEN (TIME_TO_SEC(l.early_overtime_duration) > 0 OR TIME_TO_SEC(l.regular_overtime_duration) > 0)
                     AND l.assignment_type IN ('Overtime normal','Overtime early')
                    THEN l.work_date
                END
            ),

            -- Jam lembur hari kerja
            SUM(
                CASE
                    WHEN (TIME_TO_SEC(l.early_overtime_duration) > 0 OR TIME_TO_SEC(l.regular_overtime_duration) > 0)
                     AND l.assignment_type IN ('Overtime normal','Overtime early')
                    THEN (TIME_TO_SEC(l.early_overtime_duration) + TIME_TO_SEC(l.regular_overtime_duration)) / 3600
                    ELSE 0
                END
            ),

            -- Lembur hari libur atau Minggu
            COUNT(DISTINCT
                CASE
                    WHEN (TIME_TO_SEC(l.early_overtime_duration) > 0 OR TIME_TO_SEC(l.regular_overtime_duration) > 0)
                     AND l.assignment_type IN ('Overtime holiday','Overtime sunday')
                    THEN l.work_date
                END
            ),

            -- Jam lembur hari libur atau Minggu
            SUM(
                CASE
                    WHEN (TIME_TO_SEC(l.early_overtime_duration) > 0 OR TIME_TO_SEC(l.regular_overtime_duration) > 0)
                     AND l.assignment_type IN ('Overtime holiday','Overtime sunday')
                    THEN (TIME_TO_SEC(l.early_overtime_duration) + TIME_TO_SEC(l.regular_overtime_duration)) / 3600
                    ELSE 0
                END
            ),

            -- Present days
						COUNT(DISTINCT
								CASE
										WHEN
												DAYNAME(l.work_date) <> 'Sunday'
												AND NOT EXISTS (
														SELECT 1
														FROM tmmst.m_holidays h
														WHERE h.date = l.work_date
												)
												AND l.has_attendance = 1
												AND (l.attendance_code_id IS NULL OR l.attendance_code_id <> 16)
												AND NOT EXISTS (
														SELECT 1
														FROM tmhrm.tma_leave_request lr
														WHERE lr.employee_id = l.employee_id
															AND lr.stat_confirm = 1
															AND lr.is_active = 1
															AND l.work_date BETWEEN lr.start_date AND lr.end_date
												)
										THEN l.work_date
								END
						) AS present_days,

            -- Hari absen
						COUNT(DISTINCT
								CASE
										WHEN l.attendance_code_id = 16
										THEN l.work_date
								END
						) AS absent_days,

            -- Hitung sakit
						(
								SELECT COUNT(*)
								FROM tmhrm.tma_leave_request lr
								JOIN (
										WITH RECURSIVE date_range AS (
												SELECT v_start_date AS d
												UNION ALL
												SELECT DATE_ADD(d, INTERVAL 1 DAY)
												FROM date_range
												WHERE d < v_end_date
										)
										SELECT d FROM date_range
								) wd
										ON wd.d BETWEEN lr.start_date AND lr.end_date
								LEFT JOIN tmmst.m_holidays h 
										ON h.date = wd.d
								WHERE lr.employee_id = l.employee_id
									AND lr.leave_type = 'SAKIT'
									AND lr.stat_confirm = 1
									AND lr.is_active = 1
									AND DAYNAME(wd.d) <> 'Sunday'
									AND h.date IS NULL
						) AS sick_days,
						
						-- Hitung Cuti			
						(
								SELECT COUNT(*)
								FROM tmhrm.tma_leave_request lr
								JOIN (
										WITH RECURSIVE date_range AS (
												SELECT v_start_date AS d
												UNION ALL
												SELECT DATE_ADD(d, INTERVAL 1 DAY)
												FROM date_range
												WHERE d < v_end_date
										)
										SELECT d FROM date_range
								) wd
										ON wd.d BETWEEN lr.start_date AND lr.end_date
								LEFT JOIN tmmst.m_holidays h 
										ON h.date = wd.d
								WHERE lr.employee_id = l.employee_id
									AND lr.leave_type IN ('CUTI')
									AND lr.stat_confirm = 1
									AND lr.is_active = 1
									AND DAYNAME(wd.d) <> 'Sunday'
									AND h.date IS NULL
						) AS leave_days,

						-- Hitung Permission (IJIN MENGETAHUI)
						(
								SELECT COUNT(*)
								FROM tmhrm.tma_leave_request lr
								JOIN (
										WITH RECURSIVE date_range AS (
												SELECT v_start_date AS d
												UNION ALL
												SELECT DATE_ADD(d, INTERVAL 1 DAY)
												FROM date_range
												WHERE d < v_end_date
										)
										SELECT d FROM date_range
								) wd
										ON wd.d BETWEEN lr.start_date AND lr.end_date
								LEFT JOIN tmmst.m_holidays h 
										ON h.date = wd.d
								WHERE lr.employee_id = l.employee_id
										AND lr.leave_type = 'IJIN MENGETAHUI'
										AND lr.stat_confirm = 1
										AND lr.is_active = 1
										AND DAYNAME(wd.d) <> 'Sunday'
										AND h.date IS NULL
						) AS acknowledged_count,

						-- Hitung Permission (IJIN MENYETUJUI)
						(
								SELECT COUNT(*)
								FROM tmhrm.tma_leave_request lr
								JOIN (
										WITH RECURSIVE date_range AS (
												SELECT v_start_date AS d
												UNION ALL
												SELECT DATE_ADD(d, INTERVAL 1 DAY)
												FROM date_range
												WHERE d < v_end_date
										)
										SELECT d FROM date_range
								) wd
										ON wd.d BETWEEN lr.start_date AND lr.end_date
								LEFT JOIN tmmst.m_holidays h 
										ON h.date = wd.d
								WHERE lr.employee_id = l.employee_id
										AND lr.leave_type = 'IJIN MENYETUJUI'
										AND lr.stat_confirm = 1
										AND lr.is_active = 1
										AND DAYNAME(wd.d) <> 'Sunday'
										AND h.date IS NULL
						) AS approved_leave_count,

						-- Emergency Call (format jam.menit)
						SUM(
						DISTINCT
						CASE
							WHEN l.assignment_type = 'Emergency call'
							 AND l.emcall_in IS NOT NULL
							 AND l.emcall_out IS NOT NULL
							THEN TIMESTAMPDIFF(MINUTE, l.emcall_in, l.emcall_out) / 60
						END
					)

        FROM
        (
            SELECT
                al.*,
								sa.assignment_type,
								d.emcall_in,
								d.emcall_out,
								
								
								CASE
									WHEN al.ta_start IS NOT NULL THEN 1
									ELSE 0
								END AS has_attendance,
								CASE
									WHEN sa.assignment_type IN (
											'Overtime normal',
											'Overtime early',
											'Overtime holiday',
											'Overtime sunday'
									)
									THEN 1
									ELSE 0
								END AS has_overtime_so,

								-- Jam shift final (SO > master shift)
								COALESCE(TIME(d.ta_start), sd.start_time) AS shift_start,
								COALESCE(TIME(d.ta_end),   sd.end_time)   AS shift_end,

								-- Hitung menit telat (pakai SO kalau ada)
								CASE
										WHEN TIME(al.ta_start) > COALESCE(TIME(d.ta_start), sd.start_time)
										THEN TIMESTAMPDIFF(
														MINUTE,
														COALESCE(TIME(d.ta_start), sd.start_time),
														TIME(al.ta_start)
												 )
										ELSE 0
								END AS late_min,

								-- Hitung menit pulang cepat (pakai SO kalau ada)
								CASE
										WHEN TIME(al.ta_end) < COALESCE(TIME(d.ta_end), sd.end_time)
										THEN TIMESTAMPDIFF(
														MINUTE,
														TIME(al.ta_end),
														COALESCE(TIME(d.ta_end), sd.end_time)
												 )
										ELSE 0
								END AS early_out_min


            FROM tmhrm.tma_attendance_logs al

            LEFT JOIN tmhrm.tma_so_ass_detail d
                ON d.employee_id = al.employee_id
               AND d.period_id   = al.period_id

            LEFT JOIN tmhrm.tma_so_ass sa
                ON sa.sa_id = d.sa_id

            -- Shift aktif (Change shift override) + filter hari
            LEFT JOIN tmmst.m_shifts_details sd
                ON sd.shift_id =
                    CASE
                        WHEN sa.assignment_type = 'Change shift'
                            THEN sa.shift_dst_id
                        ELSE al.shift_id
                    END
               AND sd.shift_day = DAYNAME(al.work_date)

            WHERE al.period_id = v_period_id
              AND al.work_date BETWEEN v_start_date AND v_end_date
        ) l

        JOIN tmhrm.emp e
            ON e.employee_id = p_employee_id
           AND e.payroll_cycle = v_payroll_cycle

        GROUP BY l.employee_id

        ON DUPLICATE KEY UPDATE
            workday_days           = VALUES(workday_days),
            late_under_5_count     = VALUES(late_under_5_count),
            late_under_5_minutes   = VALUES(late_under_5_minutes),
            late_over_5_count      = VALUES(late_over_5_count),
            late_over_5_minutes    = VALUES(late_over_5_minutes),
            early_out_days         = VALUES(early_out_days),
            early_out_minutes      = VALUES(early_out_minutes),
						break_in_late_count 	 = VALUES(break_in_late_count),
            overtime_workday_days  = VALUES(overtime_workday_days),
            overtime_workday_hours = VALUES(overtime_workday_hours),
            overtime_holiday_days  = VALUES(overtime_holiday_days),
            overtime_holiday_hours = VALUES(overtime_holiday_hours),
            present_days           = VALUES(present_days),
            absent_days            = VALUES(absent_days),
						emergency_call_hours   = VALUES(emergency_call_hours),
						approved_leave_count   = VALUES(approved_leave_count),
						leave_days      			 = VALUES(leave_days),
						dayoff_days  					 = VALUES(dayoff_days),
						holiday_days 					 = VALUES(holiday_days),
						acknowledged_count 			 = VALUES(acknowledged_count),
            sick_days              = VALUES(sick_days);

END proc_main
;;
delimiter ;

-- ----------------------------
-- Procedure structure for sp_process_attlogs
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_process_attlogs`;
delimiter ;;
CREATE PROCEDURE `sp_process_attlogs`()
  COMMENT 'Fungsi ini digunakan untuk generate ke tabel attendance log dan proses ini dipanggil dari proses excel'
proc_main: BEGIN

    -- ****************************************
    --  Create by Novita Updated 24 Feb 2026
    -- ****************************************

    DECLARE done INT DEFAULT 0;

    DECLARE v_period_id BIGINT;
    DECLARE v_start_date DATE;
    DECLARE v_end_date DATE;
    DECLARE v_payroll_cycle ENUM('WEEKLY','MONTHLY');
    DECLARE v_workday_days INT;

    DECLARE cur_period CURSOR FOR
        SELECT period_id, start_date, end_date, payroll_cycle
        FROM tmpyr.payroll_periods
        WHERE is_active = 1
          AND stat_closed = 0;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    OPEN cur_period;

    period_loop: LOOP

        FETCH cur_period
        INTO v_period_id, v_start_date, v_end_date, v_payroll_cycle;

        IF done = 1 THEN
            LEAVE period_loop;
        END IF;

        SET v_workday_days =
            CASE v_payroll_cycle
                WHEN 'WEEKLY'  THEN 6
                WHEN 'MONTHLY' THEN 25
                ELSE 1
            END;

            employee_id,
            period_id,
            device_id,
            work_date,
            ta_start,
            ta_breakout,
            ta_breakin,
            ta_end,
            ta_day,
            ta_leaveout,
            ta_leavein,
            ta_extendin,
            ta_extendout,
            workhour_duration,
            late_duration,
            break_late_duration,
            leave_duration,
            stat_overtime,
            stat_late_under_5min,
            stat_late_over_5min,
            early_overtime_duration,
            regular_overtime_duration,
            overtime_type,
            stat_normal,
            stat_present,
            attendance_code_id,
            shift_id,
            create_log
        )

        SELECT
            e.employee_id,
            v_period_id,
            r.device_id,
            r.work_date,
            r.start_datetime,
						COALESCE(r.breakout_time, TIMESTAMP(r.work_date, sd.break_out)),
						COALESCE(r.breakin_time, TIMESTAMP(r.work_date, sd.break_in)),
            r.end_datetime,
            DAYNAME(r.work_date),
            r.leave_out,
            r.leave_in,
            r.extend_in,
            r.extend_out,

            -- TOTAL WORKING HOURS
						CASE
								WHEN r.start_datetime IS NOT NULL
								 AND r.end_datetime IS NOT NULL
								THEN SEC_TO_TIME(

										TIMESTAMPDIFF(
												SECOND,
												r.start_datetime,
												r.end_datetime
										)

										- IF(
												r.breakout_time IS NOT NULL
												AND r.breakin_time IS NOT NULL,
												TIMESTAMPDIFF(
														SECOND,
														r.breakout_time,
														r.breakin_time
												),
												0
										)

										- IF(
												r.leave_out IS NOT NULL
												AND r.leave_in IS NOT NULL,
												TIMESTAMPDIFF(
														SECOND,
														r.leave_out,
														r.leave_in
												),
												0
										)

										+ IF(
												r.extend_in IS NOT NULL
												AND r.extend_out IS NOT NULL,
												TIMESTAMPDIFF(
														SECOND,
														r.extend_in,
														r.extend_out
												),
												0
										)

								)
								ELSE '00:00:00'
						END,

            -- LATE DURATION
            CASE
                WHEN sd.start_time IS NOT NULL
                 AND TIME(r.start_datetime) > sd.start_time
                THEN SEC_TO_TIME(
                        TIMESTAMPDIFF(
                            SECOND,
                            sd.start_time,
                            TIME(r.start_datetime)
                        )
                )
                ELSE '00:00:00'
            END,

            -- break late duration
            CASE
                WHEN sd.break_out IS NOT NULL 
                 AND sd.break_in IS NOT NULL
                 AND r.breakout_time IS NOT NULL
                 AND r.breakin_time IS NOT NULL
                THEN
                    CASE
                        WHEN TIMESTAMPDIFF(
                                SECOND,
                                r.breakout_time,
                                r.breakin_time
                             )
                             >
                             TIMESTAMPDIFF(
                                SECOND,
                                sd.break_out,
                                sd.break_in
                             )
                        THEN
                            SEC_TO_TIME(
                                TIMESTAMPDIFF(
                                    SECOND,
                                    r.breakout_time,
                                    r.breakin_time
                                )
                                -
                                TIMESTAMPDIFF(
                                    SECOND,
                                    sd.break_out,
                                    sd.break_in
                                )
                            )
                        ELSE '00:00:00'
                    END
                ELSE '00:00:00'
            END,

            '00:00:00',

            -- OVERTIME FLAG
            CASE
                WHEN so.assignment_type IN ('Overtime normal','Overtime holiday','Overtime sunday','Overtime early')
                THEN 1 ELSE 0
            END,

            -- FLAG TELAT < 5
            CASE
                WHEN sd.start_time IS NOT NULL
                 AND TIME(r.start_datetime) > sd.start_time
                 AND TIMESTAMPDIFF(
                        MINUTE,
                        sd.start_time,
                        TIME(r.start_datetime)
                 ) < 5
                THEN 1 ELSE 0
            END,

            -- FLAG TELAT >= 5
            CASE
                WHEN sd.start_time IS NOT NULL
                 AND TIME(r.start_datetime) > sd.start_time
                 AND TIMESTAMPDIFF(
                        MINUTE,
                        sd.start_time,
                        TIME(r.start_datetime)
                 ) >= 5
                THEN 1 ELSE 0
            END,

            -- EARLY OVERTIME
            CASE
                WHEN so.assignment_type = 'Overtime early'
                THEN SEC_TO_TIME(sod.ta_duration * 3600)
                ELSE '00:00:00'
            END,

            -- REGULAR OVERTIME
            CASE
								WHEN so.assignment_type IN (
										'Overtime normal',
										'Overtime holiday',
										'Overtime sunday'
								)
								THEN SEC_TO_TIME(sod.ta_duration * 3600)
								ELSE '00:00:00'
						END,

            -- OVERTIME TYPE
            CASE
                WHEN so.assignment_type = 'Overtime normal' THEN 'WORKDAY'
                WHEN so.assignment_type = 'Overtime holiday' THEN 'HOLIDAY'
                WHEN so.assignment_type = 'Overtime sunday' THEN 'SUNDAY'
                WHEN so.assignment_type = 'Overtime early' THEN 'EARLY'
                ELSE NULL
            END,

            -- stat_normal
            CASE
                WHEN sd.start_time IS NOT NULL
                 AND TIME(r.start_datetime) > sd.start_time
                THEN 0 ELSE 1
            END,

            -- stat_present
            CASE
                WHEN r.start_datetime IS NULL THEN 0
                ELSE 1
            END,

            -- attendance code
            CASE
                WHEN lv.leave_type = 'CUTI' THEN 15
                WHEN lv.leave_type = 'SAKIT'
                     AND lv.doctor_letter_path IS NULL THEN 12
                WHEN lv.leave_type = 'SAKIT'
                     AND lv.doctor_letter_path IS NOT NULL THEN 13
                WHEN lv.leave_type = 'IJIN'
                     AND lv.start_time <= sd.start_time THEN 3
                WHEN lv.leave_type = 'IJIN'
                     AND lv.start_time > sd.start_time
                     AND lv.end_time < sd.end_time THEN 4
                WHEN lv.leave_type = 'IJIN'
                     AND lv.end_time >= sd.end_time THEN 5
                WHEN r.start_datetime IS NULL
                     AND lv.leave_id IS NULL THEN 16
                WHEN sd.start_time IS NOT NULL
                     AND TIME(r.start_datetime) > sd.start_time
                     AND TIMESTAMPDIFF(MINUTE, sd.start_time, TIME(r.start_datetime)) < 5
                THEN 1
                WHEN sd.start_time IS NOT NULL
                     AND TIMESTAMPDIFF(MINUTE, sd.start_time, TIME(r.start_datetime)) >= 5
                THEN 2
                ELSE NULL
            END,

            COALESCE(
                CASE
                    WHEN so_shift.assignment_type = 'Shift reguler'
                    THEN sod_shift.shift_id
                END,
                e.default_shift_id
            ),
            NOW()

        FROM tmhrm.tma_rawdata r

        JOIN tmhrm.emp e
            ON e.device_pin = r.device_id
            AND e.payroll_cycle = v_payroll_cycle

        LEFT JOIN tmhrm.tma_so_ass_detail sod_shift
            ON sod_shift.employee_id = e.employee_id
            AND sod_shift.period_id = v_period_id

        LEFT JOIN tmhrm.tma_so_ass so_shift
            ON so_shift.sa_id = sod_shift.sa_id
            AND so_shift.assignment_type = 'Shift reguler'

        LEFT JOIN tmmst.m_shifts_details sd
            ON sd.shift_id = COALESCE(
                    CASE
                        WHEN so_shift.assignment_type = 'Shift reguler'
                        THEN sod_shift.shift_id
                    END,
                    e.default_shift_id
               )
            AND LOWER(sd.shift_day) = LOWER(DAYNAME(r.work_date))

        LEFT JOIN tmhrm.tma_leave_request lv
            ON lv.employee_id = e.employee_id
            AND r.work_date BETWEEN lv.start_date AND lv.end_date
            AND lv.stat_auth LIKE 'AP_%'

        LEFT JOIN tmhrm.tma_so_ass_detail sod
            ON sod.employee_id = e.employee_id
            AND sod.period_id = v_period_id
            AND DATE(sod.ta_start) = r.work_date

        LEFT JOIN tmhrm.tma_so_ass so
            ON so.sa_id = sod.sa_id

        LEFT JOIN tmmst.m_holidays h
            ON h.date = r.work_date

        WHERE r.work_date BETWEEN v_start_date AND v_end_date

        AND NOT (
            (DAYNAME(r.work_date) = 'Sunday' OR h.date IS NOT NULL)
            AND r.start_datetime IS NULL
        )

        ON DUPLICATE KEY UPDATE
            device_id = VALUES(device_id),
            ta_start = VALUES(ta_start),
            ta_breakout = COALESCE(VALUES(ta_breakout), ta_breakout),
						ta_breakin  = COALESCE(VALUES(ta_breakin), ta_breakin),
            ta_end = VALUES(ta_end),
            workhour_duration = VALUES(workhour_duration),
            late_duration = VALUES(late_duration),
            break_late_duration = VALUES(break_late_duration),
            leave_duration = VALUES(leave_duration),
            stat_overtime = VALUES(stat_overtime),
            stat_late_under_5min = VALUES(stat_late_under_5min),
            stat_late_over_5min = VALUES(stat_late_over_5min),
            early_overtime_duration = VALUES(early_overtime_duration),
            regular_overtime_duration = VALUES(regular_overtime_duration),
            overtime_type = VALUES(overtime_type),
            stat_normal = VALUES(stat_normal),
            stat_present = VALUES(stat_present),
            attendance_code_id = VALUES(attendance_code_id),
            shift_id = VALUES(shift_id),
            update_log = NOW();

    END LOOP;

    CLOSE cur_period;

END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table emp_contracts
-- ----------------------------
DROP TRIGGER IF EXISTS `trg_emp_contract_approved`;
delimiter ;;
CREATE TRIGGER `trg_emp_contract_approved` AFTER UPDATE ON `emp_contracts` FOR EACH ROW BEGIN
  IF NEW.contract_status = 'ACTIVE' THEN
    VALUES (NEW.employee_id, NEW.basic_salary, NEW.start_date, NEW.end_date);
  END IF;
END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table emp_detail
-- ----------------------------
DROP TRIGGER IF EXISTS `trg_emp_detail_check_master`;
delimiter ;;
CREATE TRIGGER `trg_emp_detail_check_master` BEFORE INSERT ON `emp_detail` FOR EACH ROW BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM tmmst.m_emp WHERE employee_id = NEW.employee_id
    ) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'employee_id tidak ditemukan di tmmst.m_emp (FK lintas-DB)';
    END IF;
END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table tma_attendance_logs
-- ----------------------------
DROP TRIGGER IF EXISTS `trg_au_attendance_logs`;
delimiter ;;
CREATE TRIGGER `trg_au_attendance_logs` BEFORE UPDATE ON `tma_attendance_logs` FOR EACH ROW BEGIN

    -- HITUNG TOTAL WORK HOURS OTOMATIS
    SET NEW.workhour_duration =
        CASE
            WHEN NEW.ta_start IS NOT NULL
             AND NEW.ta_end IS NOT NULL
            THEN SEC_TO_TIME(

                TIMESTAMPDIFF(
                    SECOND,
                    NEW.ta_start,
                    NEW.ta_end
                )

                - IF(
                    NEW.ta_breakout IS NOT NULL
                    AND NEW.ta_breakin IS NOT NULL,
                    TIMESTAMPDIFF(
                        SECOND,
                        NEW.ta_breakout,
                        NEW.ta_breakin
                    ),
                    0
                )

                - IF(
                    NEW.ta_leaveout IS NOT NULL
                    AND NEW.ta_leavein IS NOT NULL,
                    TIMESTAMPDIFF(
                        SECOND,
                        NEW.ta_leaveout,
                        NEW.ta_leavein
                    ),
                    0
                )

                + IF(
                    NEW.ta_extendin IS NOT NULL
                    AND NEW.ta_extendout IS NOT NULL,
                    TIMESTAMPDIFF(
                        SECOND,
                        NEW.ta_extendin,
                        NEW.ta_extendout
                    ),
                    0
                )
            )
            ELSE '00:00:00'
        END;


    IF  NOT (OLD.ta_start <=> NEW.ta_start)
        OR NOT (OLD.ta_end <=> NEW.ta_end)
        OR NOT (OLD.ta_breakout <=> NEW.ta_breakout)
        OR NOT (OLD.ta_breakin <=> NEW.ta_breakin)
        OR NOT (OLD.stat_present <=> NEW.stat_present)
        OR NOT (OLD.attendance_code_id <=> NEW.attendance_code_id)
        OR NOT (OLD.late_duration <=> NEW.late_duration)
        OR NOT (OLD.break_late_duration <=> NEW.break_late_duration)
        OR NOT (OLD.stat_late_under_5min <=> NEW.stat_late_under_5min)
        OR NOT (OLD.stat_late_over_5min <=> NEW.stat_late_over_5min)
        OR NOT (OLD.early_overtime_duration <=> NEW.early_overtime_duration)
        OR NOT (OLD.regular_overtime_duration <=> NEW.regular_overtime_duration)
        OR NOT (OLD.overtime_type <=> NEW.overtime_type)
        OR NOT (OLD.stat_overtime <=> NEW.stat_overtime)
        OR NOT (OLD.ta_leaveout <=> NEW.ta_leaveout)
        OR NOT (OLD.ta_leavein <=> NEW.ta_leavein)
        OR NOT (OLD.leave_duration <=> NEW.leave_duration)
    THEN

        CALL sp_patch_att_summ_by_emp(
            NEW.period_id,
            NEW.employee_id
        );

    END IF;

END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
